def _install_embedded_packages():
    """Giai ma zip nhung san thanh bytes-in-memory, dang ky truc tiep vao
    sys.path qua zipimporter (KHONG ghi file tam ra dia) - sau buoc nay,
    `import check_rule` va `import check_ip` hoat dong y het nhu khi 2 thu
    muc do nam that tren dia canh script nay."""
    raw = base64.b64decode(_EMBEDDED_PACKAGES_ZIP_B64)
    buf = io.BytesIO(raw)
    import zipimport
    # zipimport can 1 duong dan FILE that (khong nhan BytesIO truc tiep) tren
    # hau het phien ban CPython, nhung sys.path_hooks lai ho tro dang
    # "sys.path entry = duong dan .zip". Vi khong muon ghi file .zip tam ra
    # dia (giu dung tinh chat "khong dung file phu"), dung them mot ky thuat
    # phu: dang ky truc tiep 1 MetaPathFinder doc tu bytes trong bo nho, dung
    # module chuan importlib de nap tung file .py mot cach thu cong nhung
    # 100% tuong thich hanh vi package/module chuan (__package__, __path__,
    # import tuong doi "from .core import ..." deu hoat dong dung).
    zf = zipfile.ZipFile(buf)
    import importlib.abc
    import importlib.util

    # __file__ cua module nhung (embedded) can TRO VE 1 duong dan CO THAT tren
    # dia (khong phai chuoi gia "<embedded:...>") - vi check_ip/core.py dung
    # os.path.dirname(os.path.abspath(__file__)) de tinh BASE_DIR/OUTPUT_DIR khi
    # KHONG chay o dang .exe dong goi (sys.frozen=False, vd chay truc tiep
    # `python PaloRuleSearchSuite_single.py`) - dat gia __file__ NGAY CANH file
    # single-script THAT SU dang chay, de OUTPUT_DIR ra dung cho hop ly (canh
    # file .py dang chay), khong ra 1 duong dan vo nghia.
    _outer_dir = os.path.dirname(os.path.abspath(globals().get("__file__", sys.argv[0])))

    class _ZipBytesLoader(importlib.abc.Loader):
        def __init__(self, zf, name):
            self._zf = zf
            self._name = name

        def create_module(self, spec):
            return None  # dung default module creation

        def exec_module(self, module):
            src = self._zf.read(self._name).decode("utf-8")
            fake_path = os.path.join(_outer_dir, self._name.replace("/", os.sep))
            module.__file__ = fake_path
            code = compile(src, fake_path, "exec")
            exec(code, module.__dict__)

    class _ZipBytesFinder(importlib.abc.MetaPathFinder):
        def __init__(self, zf, package_roots):
            self._zf = zf
            self._roots = package_roots  # {"check_rule_pan", "check_ip_pan", "check_audit_pan"}

        def find_spec(self, fullname, path, target=None):
            top = fullname.split(".")[0]
            if top not in self._roots:
                return None
            rel = fullname.replace(".", "/")
            pkg_init = f"{rel}/__init__.py"
            mod_file = f"{rel}.py"
            names = self._zf.namelist()
            if pkg_init in names:
                spec = importlib.util.spec_from_loader(
                    fullname, _ZipBytesLoader(self._zf, pkg_init), is_package=True)
                spec.submodule_search_locations = [rel]
                return spec
            if mod_file in names:
                return importlib.util.spec_from_loader(
                    fullname, _ZipBytesLoader(self._zf, mod_file), is_package=False)
            return None

    sys.meta_path.insert(0, _ZipBytesFinder(zf, {"check_rule_pan", "check_ip_pan", "check_audit_pan"}))


import zipfile  # noqa: E402 (dung trong _install_embedded_packages o tren)
_install_embedded_packages()

# ============================================================================
# TU DAY TRO XUONG: y het noi dung main.py goc (KHONG doi logic gi ca)
# ============================================================================
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
main.py - Diem khoi chay CHUNG cua PaloRuleSearch Suite.

Suite nay CHI lam 1 viec DUY NHAT: dung 1 cua so tk.Tk() goc, gan 1
ttk.Notebook 3 tab len tren, va nhung nguyen GIAO DIEN GOC cua 3 tool doc lap
vao 3 tab do:

    Tab "CHECK RULE"  -> check_rule.gui.PANOSCheckerGUI (tool #1: kiem tra
                          request ket noi moi co duoc rule nao cho phep chua)
    Tab "CHECK IP"    -> check_ip.gui.App               (tool #2: tra cuu
                          Security Rule/NAT Rule lien quan toi 1 danh sach IP)
    Tab "CHECK AUDIT" -> check_audit.gui.App               (tool #3: kiem tra
                          Shadow / Disabled / Overly Permissive Rules)

KHONG co logic nghiep vu nao nam trong file nay - moi xu ly (parse config,
resolve object/group, matching, xuat Excel...) van nam nguyen trong tung
package con (check_rule/, check_ip/), khong doi gi so voi luc con la 3 tool
rieng biet. 3 package nay KHONG import lan nhau (xem check_rule/__init__.py,
check_ip/__init__.py) - sua tinh nang cua 1 tool se KHONG BAO GIO can dong
cham toi file cua tool con lai, va cung khong lam anh huong hanh vi cua tool
con lai.

Dong goi .exe (build 1 file duy nhat):
    pyinstaller --onefile --noconsole --name PaloPANORAMA PaloPANORAMA_single.py

(Xem them tools/build_panorama_single.py de sinh lai ban gop PaloPANORAMA_single.py
tu 3 package - KHONG sua tay file gop.)
"""

import sys
import tkinter as tk
from tkinter import ttk, messagebox

from check_rule_pan.gui import PANOSCheckerGUI
from check_ip_pan.gui import App as CheckIPApp
from check_audit_pan.gui import App as CheckAuditApp

APP_TITLE = "PAN-OS Suite (PANORAMA) - Check Rule & Check IP & Check Audit"


def build_app(root: tk.Tk):
    """Dung Notebook 3 tab, moi tab la giao dien GOC (khong sua logic) cua 1
    tool doc lap. Tra ve (notebook, tab_check_rule, tab_check_ip, tab_check_audit) de noi goi
    (vd ham main() hoac 1 file test) co the thao tac them neu can."""
    root.title(APP_TITLE)
    root.geometry("1000x820")
    root.minsize(900, 720)

    try:
        style = ttk.Style()
        if "clam" in style.theme_names():
            style.theme_use("clam")
    except Exception:
        pass

    notebook = ttk.Notebook(root)
    notebook.pack(fill="both", expand=True)

    # ---- Tab 1: CHECK RULE (tool #1 - nguyen ven, khong sua logic) ----
    tab_check_rule = PANOSCheckerGUI(notebook)
    tab_check_rule.pack(fill="both", expand=True)
    notebook.add(tab_check_rule, text="CHECK RULE")

    # ---- Tab 2: CHECK IP (tool #2 - nguyen ven, khong sua logic) ----
    tab_check_ip = CheckIPApp(notebook)
    tab_check_ip.pack(fill="both", expand=True)
    notebook.add(tab_check_ip, text="CHECK IP")

    # ---- Tab 3: CHECK AUDIT (tool #3 - nguyen ven, khong sua logic) ----
    tab_check_audit = CheckAuditApp(notebook)
    tab_check_audit.pack(fill="both", expand=True)
    notebook.add(tab_check_audit, text="CHECK AUDIT")

    def on_close():
        # Huy moi tac vu dang chay o CA 3 tab truoc khi destroy cua so. Tab
        # nao con worker thread cham vao widget sau khi destroy se nem
        # RuntimeError("main thread is not in main loop") - nen CA 3 tab
        # deu phai co shutdown() va deu phai duoc goi o day.
        for tab in (tab_check_rule, tab_check_ip, tab_check_audit):
            try:
                tab.shutdown()
            except Exception:
                pass
        root.destroy()

    root.protocol("WM_DELETE_WINDOW", on_close)
    return notebook, tab_check_rule, tab_check_ip, tab_check_audit


def main():
    try:
        root = tk.Tk()
        build_app(root)
        root.mainloop()
    except Exception as e:
        try:
            messagebox.showerror("Loi khoi dong", f"Khong the khoi dong chuong trinh:\n{e}")
        except Exception:
            print(f"FATAL ERROR: {e}", file=sys.stderr)


if __name__ == "__main__":
    main()

